def longest_consecutive_subsequence(arr):
    """
    Returns the length of the longest subsequence where each element has a 
    difference of one from its neighboring elements.
    """
    if not arr:
        return 0

    arr = sorted(set(arr))
    longest_streak = 1
    current_streak = 1

    for i in range(1, len(arr)):
        if arr[i] == arr[i - 1] + 1:
            current_streak += 1
        else:
            longest_streak = max(longest_streak, current_streak)
            current_streak = 1

    return max(longest_streak, current_streak)

