def calculate_grade_points(score):
    """
    Calculates the grade points for a given score.

    Parameters:
    score (int): The score for which the grade points are to be calculated.

    Returns:
    float: The grade points corresponding to the input score.
    """
    if score >= 90:
        return 4.0
    elif score >= 87:
        return 3.7
    elif score >= 83:
        return 3.3
    elif score >= 80:
        return 3.0
    elif score >= 77:
        return 2.7
    elif score >= 73:
        return 2.3
    elif score >= 70:
        return 2.0
    elif score >= 67:
        return 1.7
    elif score >= 63:
        return 1.3
    elif score >= 60:
        return 1.0
    else:
        return 0.0

