def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest strictly increasing subsequence in the given array.
    """
    if not arr:
        return 0

    length = len(arr)
    lis = [1] * length

    for i in range(1, length):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

