def camel_to_snake(camel_str):
    """
    Converts a given camel case string to snake case.
    """
    snake_str = ''
    for char in camel_str:
        if char.isupper():
            if snake_str:
                snake_str += '_'
            snake_str += char.lower()
        else:
            snake_str += char
    return snake_str

```

