def count_status_codes(logs: list) -> dict:
    """
    Processes a list of HTTP request logs and returns a dictionary with the count 
    of occurrences for each HTTP status code.
    """
    status_code_count = {}

    for log in logs:
        status_code = log.split()[-1]
        if status_code in status_code_count:
            status_code_count[status_code] += 1
        else:
            status_code_count[status_code] = 1

    return status_code_count

```

