def factorial(n):
    """
    Returns the factorial of a number n using recursion.
    Factorial of n (n!) is the product of all positive integers less than or equal to n.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return n * factorial(n - 1)

