def reverse_string(s: str) -> str:
    """
    Returns a string where the characters are reversed while preserving the positions of the spaces.
    """
    characters = [char for char in s if char != ' ']
    result = []
    for char in s:
        if char == ' ':
            result.append(char)
        else:
            result.append(characters.pop())
    return ''.join(result)

