def shift_encrypt(text):
    """
    Encrypts the given text by shifting each letter by one position in the alphabet.
    Non-letter characters are not modified.
    """
    result = []
    for char in text:
        if char.isalpha():
            if char.islower():
                # handle lowercase letters
                new_char = chr(((ord(char) - ord('a') + 1) % 26) + ord('a'))
            elif char.isupper():
                # handle uppercase letters
                new_char = chr(((ord(char) - ord('A') + 1) % 26) + ord('A'))
            result.append(new_char)
        else:
            # non-letter characters remain unchanged
            result.append(char)
    return ''.join(result)

