def caesar_cipher(text, shift):
    """
    Encodes or decodes a text using a Caesar cipher with the given shift.

    :param text: The string to encode or decode.
    :param shift: The number of positions to shift the characters.
    :return: The encoded or decoded string.
    """
    result = []

    for char in text:
        if char.isalpha():
            shift_amount = (ord('A') if char.isupper() else ord('a'))
            result.append(
                chr((ord(char) - shift_amount + shift) % 26 + shift_amount)
            )
        else:
            result.append(char)

    return ''.join(result)

