def fibonacci(n):
    """
    Returns the nth Fibonacci number using fast doubling method.
    This method is efficient for large values of n.
    """
    def fib(n):
        if n == 0:
            return (0, 1)
        else:
            a, b = fib(n // 2)
            c = a * ((b << 1) - a)
            d = a * a + b * b
            if n & 1:
                return (d, c + d)
            else:
                return (c, d)

    return fib(n)[0]

