def format_board(state):
    """
    Returns a string representation of the tic-tac-toe board's current state.
    """
    symbols = {0: '{}', 1: 'X', -1: '-'}
    board = []

    for i in range(9):
        if state[i] == 0:
            board.append(symbols[state[i]].format(i+1))
        else:
            board.append(symbols[state[i]])

    formatted_board = """
  {0} | {1} | {2}
  ---------
  {3} | {4} | {5}
  ---------
  {6} | {7} | {8}
    """.format(*board)
    return formatted_board.strip()

