def check_balanced_parentheses(s):
    """
    Checks if the parentheses in the string s are balanced.

    Parameters:
    s (str): The input string containing parentheses.

    Returns:
    tuple: (bool, int or None) - A tuple where the first element is True if the parentheses are balanced, 
                                    False otherwise. The second element is the position of the first unbalanced 
                                    parenthesis (0-based index), or None if parentheses are balanced.
    """
    stack = []
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                return (False, i)

    if stack:
        return (False, stack[0])

    return (True, None)

```

