def final_position(initial_position: tuple, moves: list) -> tuple:
    """
    Compute the final position of the robot after executing the moves.

    :param initial_position: A tuple (x, y) representing the initial coordinates.
    :param moves: A list of characters representing moves: 'U', 'D', 'L', and 'R'.
    :return: A tuple representing the final coordinates (x, y).
    """
    x, y = initial_position

    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return (x, y)

