def generate_palindromic_substrings(s: str) -> list:
    """
    Function to return all unique palindromic substrings.
    """
    def is_palindrome(sub):
        return sub == sub[::-1]

    palindromes = set()
    n = len(s)

    for i in range(n):
        for j in range(i, n):
            substring = s[i:j + 1]
            if is_palindrome(substring):
                palindromes.add(substring)

    return sorted(palindromes)

```

