from typing import List, Dict


def aggregate_sales(data: List[List[Dict[str, int]]]) -> Dict[str, int]:
    """
    Aggregates sales data from multiple regions and returns total sales per month.

    :param data: List of lists containing dictionaries with sales data.
    :return: A dictionary with the total sales per month.
    """
    sales_aggregation = {}

    for region_data in data:
        for entry in region_data:
            month = entry["month"]
            sales = entry["sales"]
            if month in sales_aggregation:
                sales_aggregation[month] += sales
            else:
                sales_aggregation[month] = sales

    return sales_aggregation

```

