def depth_first_search(graph, start, end):
    """
    Determines if there is a path from start to end in the given graph using Depth-First Search (DFS).

    :param graph: Dict[str, List[str]] - A dictionary representing an adjacency list of the graph.
    :param start: str - The starting node of the search.
    :param end: str - The target node to find.
    :return: Boolean - True if a path exists from start to end, False otherwise.
    """
    def dfs(node, visited):
        if node == end:
            return True
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if dfs(neighbor, visited):
                    return True
        return False

    return dfs(start, set())

```

