def longest_sequence(s: str) -> tuple[str, int]:
    """
    Returns a tuple containing the character with the longest sequence in the string
    and the length of that sequence. If the string is empty, return an empty string and zero.
    """
    if not s:
        return ("", 0)

    max_char = s[0]
    max_length = 1

    current_char = s[0]
    current_length = 1

    for char in s[1:]:
        if char == current_char:
            current_length += 1
        else:
            if current_length > max_length:
                max_char = current_char
                max_length = current_length
            current_char = char
            current_length = 1

    # final check at the end of the loop
    if current_length > max_length:
        max_char = current_char
        max_length = current_length

    return (max_char, max_length)

