def count_characters(input_string: str) -> dict:
    """
    Returns a dictionary representing the frequency of each character in the input string, case-insensitive.

    Args:
    input_string (str): The string whose characters' frequencies are to be counted.

    Returns:
    dict: A dictionary with lowercase alphabetic characters as keys and their frequencies as values.
    """
    frequency = {}

    for char in input_string:
        if char.isalpha():
            char = char.lower()
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

    return frequency

```

