def generate_setup_cfg(config: dict) -> str:
    """
    Converts a given dictionary to the setup.cfg file format.

    Args:
    config (dict): A dictionary containing sections and their options.

    Returns:
    str: A string representation of the setup.cfg file.
    """
    lines = []
    for section, options in config.items():
        lines.append(f'[{section}]')
        for option, value in options.items():
            if isinstance(value, list):
                lines.append(f'{option}={value[0]}')
                for item in value[1:]:
                    lines.append(f' {" " * len(option)} {item}')
            else:
                lines.append(f'{option}={value}')
        lines.append('')  # Blank line between sections

    return '\n'.join(lines)

```

