def overlapping_scores(students: list) -> dict:
    """
    Given a list of student dictionaries with subject names as keys and scores as values,
    returns a dictionary where each key is a subject and the value is a set of scores
    that appear more than once across all students for that subject.
    """
    if not students:
        return {}

    from collections import defaultdict

    # Intermediate storage
    score_count = defaultdict(lambda: defaultdict(int))

    # Count scores for each subject
    for student in students:
        for subject, score in student.items():
            score_count[subject][score] += 1

    # Find scores that appear more than once
    result = {}
    for subject, scores in score_count.items():
        overlapping = {score for score, count in scores.items() if count > 1}
        if overlapping:
            result[subject] = overlapping

    return result

```

