def shift_characters(input_string):
    """
    Returns a new string where each character in the original string
    is replaced by the next character in the ASCII sequence.
    If the character is 'z' or 'Z', it wraps around to 'a' or 'A' respectively.
    Non-alphabetical characters remain unchanged.
    """
    result = []
    for char in input_string:
        if char.isalpha():
            if char == 'z':
                result.append('a')
            elif char == 'Z':
                result.append('A')
            else:
                result.append(chr(ord(char) + 1))
        else:
            result.append(char)
    return ''.join(result)

```

