def sum_list_values(input_dict):
    """
    Takes a dictionary where keys are strings and values are lists of integers.
    Returns a new dictionary where the values are the sum of the integers in the lists.

    If non-list values or lists with non-integer elements are encountered,
    returns an error message for those keys.
    """
    output_dict = {}

    for key, value in input_dict.items():
        if not isinstance(value, list):
            output_dict[key] = 'Error: contains non-list value'
            continue

        try:
            output_dict[key] = sum(value)
        except TypeError:
            output_dict[key] = 'Error: contains non-integer elements'

    return output_dict

```

