def count_characters(input_string):
    """
    Returns a dictionary where the keys are unique characters in the input_string
    and the values are the counts of each character's occurrence. Whitespace is ignored.
    Uppercase and lowercase letters are considered distinct.
    """
    character_counts = {}
    for char in input_string:
        if char.isspace():
            continue
        if char in character_counts:
            character_counts[char] += 1
        else:
            character_counts[char] = 1
    return character_counts

```

