def merge_dictionaries(d1, d2):
    """
    Merges two dictionaries d1 and d2.

    If a key exists in both dictionaries, the function will combine their values into a list.
    """
    result = {}

    for key in d1:
        if key in d2:
            val_d1 = d1[key] if isinstance(d1[key], list) else [d1[key]]
            val_d2 = d2[key] if isinstance(d2[key], list) else [d2[key]]
            result[key] = val_d1 + val_d2
        else:
            result[key] = d1[key]

    for key in d2:
        if key not in result:
            result[key] = d2[key]

    return result

```

