    """
    employee_map = {emp['id']: emp for emp in employees}

    def calculate_total_salary(employee_id):
        total_salary = employee_map[employee_id]['salary']
        subordinates = [emp['id'] for emp in employees if emp['manager_id'] == employee_id]
        for subordinate in subordinates:
            total_salary += calculate_total_salary(subordinate)
        return total_salary

    return calculate_total_salary(target_id)

```

