def reverse_alphabet_shift(s):
    """
    This function takes a string consisting of lowercase alphabets
    and returns another string where 'a' shifts to 'z', 'b' shifts to 'y', and so on.
    Non-alphabet characters are preserved in their positions.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr(219 - ord(c))
        return c

    return ''.join(shift_char(c) for c in s)

```

