def is_balanced(expression):
    """
    Returns True if the parentheses, brackets, and braces in the expression 
    are correctly balanced and nested, otherwise returns False.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs.keys():
            if not stack or pairs[char] != stack.pop():
                return False
    return not stack

```

