def word_frequency(sentence):
    """
    Returns a dictionary with each unique word as the key and its frequency 
    in the sentence as the value. The words are case insensitive.
    """
    words = sentence.lower().split()
    frequency = {}

    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

```

