def combine_dicts(dict1, dict2):
    """
    Combines two dictionaries by summing values of keys that appear in both dictionaries.
    If a key exists in only one of the dictionaries, its value is included as is in the resulting dictionary.

    Parameters:
    dict1 (dict): First dictionary with integer values.
    dict2 (dict): Second dictionary with integer values.

    Returns:
    dict: A new dictionary with combined keys and summed values where applicable.
    """
    result = {}
    for key in dict1:
        if key in dict2:
            result[key] = dict1[key] + dict2[key]
        else:
            result[key] = dict1[key]

    for key in dict2:
        if key not in result:
            result[key] = dict2[key]

    return result

```

