def parse_metadata(metadata):
    """
    Parses the provided metadata dictionary and transforms it into a dictionary where each key is a document ID
    and each value is another dictionary of metadata for that document.

    :param metadata: dict - dictionary containing metadata for multiple documents
    :return: dict - structured dictionary with document ID as keys and their respective metadata as values
    """
    parsed_metadata = {}
    for document in metadata.get('documents', []):
        document_id = document.get('id')
        if document_id:
            parsed_metadata[document_id] = {key: value for key, value in document.items() if key != 'id'}
    return parsed_metadata

```

