def create_nested_dict(keys, values):
    """
    Create a nested dictionary from a list of keys and values.

    :param keys: List of lists representing the keys (nested structure)
    :param values: List of values corresponding to the last keys
    :return: A nested dictionary structure
    """
    if len(keys) != len(values):
        raise ValueError("Length of keys and values must be the same")

    nested_dict = {}

    for i, key_list in enumerate(keys):
        current = nested_dict
        for key in key_list[:-1]:
            if key not in current:
                current[key] = {}
            current = current[key]
        current[key_list[-1]] = values[i]

    return nested_dict

```

