import re


def replace_punctuation(input_str, replacement_char, exceptions=[]):
    """
    Replaces all punctuation in the input_str with replacement_char,
    except for punctuations in the exceptions list.

    Args:
    input_str (str): The input string.
    replacement_char (str): The character to replace the punctuation with.
    exceptions (list of str): List of substrings where punctuation shouldn't be replaced.

    Returns:
    str: The string with punctuation replaced.
    """
    preserved_indices = set()

    for ex in exceptions:
        for match in re.finditer(re.escape(ex), input_str):
            for i in range(match.start(), match.end()):
                preserved_indices.add(i)

    def is_punctuation(c):
        return re.match(r'[^\w\s]', c)

    result = []
    for i, c in enumerate(input_str):
        if is_punctuation(c) and i not in preserved_indices:
            result.append(replacement_char)
        else:
            result.append(c)

    return ''.join(result)

```

