def first_odd_occurrence(nums):
    """
    Returns the first integer that appears an odd number of times in the list.
    If no such integer is found, returns None.
    """
    count_dict = {}
    for num in nums:
        count_dict[num] = count_dict.get(num, 0) + 1

    for num in nums:
        if count_dict[num] % 2 != 0:
            return num

    return None

```

