```python
def rotate_byte_sequence(byte_seq, direction, num_bits):
    """
    Performs a circular bitwise rotation on a sequence of bytes.

    Parameters:
    byte_seq (bytes): The sequence of bytes to rotate.
    direction (str): The direction of rotation ('left' or 'right').
    num_bits (int): The number of bits to rotate.

    Returns:
    bytes: The rotated byte sequence.
    """

    def rotate_left(byte, bits):
        return ((byte << bits) & 0xFF) | (byte >> (8 - bits))

    def rotate_right(byte, bits):
        return (byte >> bits) | ((byte << (8 - bits)) & 0xFF)

    rotated_seq = bytearray()

    for byte in byte_seq:
        if direction == 'left':
            rotated_seq.append(rotate_left(byte, num_bits))
        elif direction == 'right':
            rotated_seq.append(rotate_right(byte, num_bits))
        else:
            raise ValueError("Invalid direction; must be 'left' or 'right'")

    return bytes(rotated_seq)

```

