def character_count(s):
    """
    Returns a dictionary with the count of each character in the string `s`.
    Spaces are ignored and the function is case-sensitive.
    """
    count_dict = {}
    for char in s:
        if char != ' ':
            if char in count_dict:
                count_dict[char] += 1
            else:
                count_dict[char] = 1
    return count_dict

```

