def merge_dicts(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary. If a key appears in more 
    than one dictionary, its values are combined into a sorted list.

    :param dict1: first dictionary
    :param dict2: second dictionary
    :param dict3: third dictionary
    :return: merged dictionary with sorted lists of values
    """
    merged_dict = {}

    for d in (dict1, dict2, dict3):
        for key, value in d.items():
            if key in merged_dict:
                if isinstance(merged_dict[key], list):
                    merged_dict[key].append(value)
                else:
                    merged_dict[key] = [merged_dict[key], value]
            else:
                merged_dict[key] = value

    for key in merged_dict:
        if isinstance(merged_dict[key], list):
            merged_dict[key].sort()
        else:
            merged_dict[key] = [merged_dict[key]]

    return merged_dict

```

