def catalan_number(n, memo=None):
    """
    Returns the nth Catalan number using memoization.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 1

    result = 0
    for i in range(n):
        result += catalan_number(i, memo) * catalan_number(n - 1 - i, memo)

    memo[n] = result
    return result

```

