def interchange_quotations(s):
    """
    Interchanges single and double quotation marks in the string.

    Args:
    s (str): The input string.

    Returns:
    str: The string with single and double quotation marks interchanged.
    """
    temp = []
    for ch in s:
        if ch == "'":
            temp.append('"')
        elif ch == '"':
            temp.append("'")
        else:
            temp.append(ch)
    return ''.join(temp)

```

