def customer_transactions(transactions):
    """
    Returns a dictionary of dictionaries, where each customer ID maps to a dictionary
    of transactions and their frequencies, sorted alphabetically by transaction keys.
    """
    result = {}
    for customer_id, items in transactions.items():
        item_count = {}
        for item in items:
            if item in item_count:
                item_count[item] += 1
            else:
                item_count[item] = 1
        # sorting the inner dictionary alphabetically by keys
        sorted_item_count = dict(sorted(item_count.items()))
        result[customer_id] = sorted_item_count
    return result

```

