def decimal_to_hexadecimal(n):
    """
    Converts a decimal number to its hexadecimal representation.
    For negative numbers, returns the two's complement hexadecimal
    representation using a 32-bit integer format.
    """
    if n >= 0:
        return hex(n)[2:].upper()
    else:
        return hex((1 << 32) + n)[2:].upper()

