def categorize_by_food_type(people, food_types):
    """
    Categorizes each person by their favorite food type.

    Parameters:
    people (list of tuples): A list where each tuple contains a person's name and their favorite food.
    food_types (dict): A dictionary where keys are food types and values are lists of foods.

    Returns:
    dict: A dictionary where keys are food types and values are lists of people who like that type of food.
    """
    categorized_dict = {food_type: [] for food_type in food_types}

    food_to_type = {}
    for food_type, foods in food_types.items():
        for food in foods:
            food_to_type[food] = food_type

    for person, favorite_food in people:
        if favorite_food in food_to_type:
            categorized_dict[food_to_type[favorite_food]].append(person)

    return categorized_dict

```

