def process_items(items):
    """
    Processes a list of integers and returns a dictionary with the frequency
    and percentage of the total count for each integer.
    """
    if not items:
        return {}

    item_count = len(items)
    frequency = {}

    for item in items:
        if item in frequency:
            frequency[item]['count'] += 1
        else:
            frequency[item] = {'count': 1}

    for item in frequency:
        frequency[item]['percentage'] = (frequency[item]['count'] / item_count) * 100

    return frequency

```

