def average_age_by_gender(people):
    """
    Calculates the average age for each gender.

    :param people: List of dictionaries, where each dictionary contains 'name', 'age', and 'gender'.
    :return: Dictionary with genders as keys and their respective average ages as values.
    """
    if not people:
        return {}

    genders = {}
    for person in people:
        gender = person['gender']
        age = person['age']
        if gender in genders:
            genders[gender].append(age)
        else:
            genders[gender] = [age]

    avg_age_by_gender = {gender: sum(ages) / len(ages) for gender, ages in genders.items()}

    return avg_age_by_gender

```

