def flatten_json(nested_json, delimiter='.'):
    """
    Flattens a nested json dictionary.

    :param nested_json: The json to flatten
    :param delimiter: The delimiter used to denote hierarchy. Defaults to '.'
    :return: A flat dictionary
    """
    def flatten(x, name=''):
        if type(x) is dict:
            for key in x:
                flatten(x[key], name + key + delimiter)
        elif type(x) is list:
            i = 0
            for elem in x:
                flatten(elem, name + str(i) + delimiter)
                i += 1
        else:
            out[name[:-1]] = x

    out = {}
    flatten(nested_json)
    return out

```

