def factorial(n):
    """
    Returns the factorial of a non-negative integer `n` using recursion.
    If `n` is negative, returns a message indicating the error.
    """
    if n < 0:
        return "Factorials for negative numbers are not defined."
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

