def check_prime_and_get_divisors(n):
    """
    Checks if a number `n` is prime. If it is prime, returns True.
    If it is not prime, returns a list of its divisors.
    """
    if n <= 1:
        return False, []

    divisors = []
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)

    if len(divisors) == 0:
        return True, []
    else:
        return False, sorted(divisors)

```

