import heapq


def topKFrequent(nums, k):
    """
    Returns the k most frequent elements along with their frequencies.
    """
    count = {}
    for num in nums:
        if num not in count:
            count[num] = 1
        else:
            count[num] += 1

    heap = []
    for key, value in count.items():
        heapq.heappush(heap, (value, key))

    # Get the k largest elements and modify to return (number, frequency)
    return [(key, value) for value, key in heapq.nlargest(k, heap)]

```

