def string_to_number(s):
    """
    Converts a string to a number, handling both integers and floating-point numbers.

    Parameters:
    s (str): The string to convert.

    Returns:
    int or float: The converted number.

    Raises:
    ValueError: If the string does not represent a valid number.
    """
    try:
        if '.' in s:
            return float(s)
        else:
            return int(s)
    except ValueError:
        raise ValueError(f"Cannot convert string '{s}' to a number")

