def compare_dicts(dict1, dict2):
    """
    Compares two dictionaries and returns a tuple of three dictionaries:
    - keys with different values
    - keys only in dict1
    - keys only in dict2
    """
    diffs = {}
    only_in_dict1 = {}
    only_in_dict2 = {}

    # Find common and differing keys
    all_keys = set(dict1.keys()).union(set(dict2.keys()))

    for key in all_keys:
        if key in dict1 and key in dict2:
            if dict1[key] != dict2[key]:
                diffs[key] = (dict1[key], dict2[key])
        elif key in dict1:
            only_in_dict1[key] = dict1[key]
        else:
            only_in_dict2[key] = dict2[key]

    return diffs, only_in_dict1, only_in_dict2

```

