def create_weighted_graph(edges):
    """
    Creates a weighted adjacency list representation of the graph.

    Parameters:
    edges (list of tuples): Each tuple is of the form (u, v, w) where u and v are nodes,
                            and w is the weight of the edge from u to v.

    Returns:
    dict: Adjacency list representation of the graph.
    """
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = w
        graph[v][u] = w  # If the graph is undirected

    return graph

```

