def calculator(operation, a, b):
    """
    Performs basic arithmetic operations based on the given operation.

    :param operation: A string representing the operation ('add', 'subtract', 'multiply', 'divide')
    :param a: The first number (int or float)
    :param b: The second number (int or float)
    :return: The result of the operation
    """
    if operation == 'add':
        return a + b
    elif operation == 'subtract':
        return a - b
    elif operation == 'multiply':
        return a * b
    elif operation == 'divide':
        if b == 0:
            return "Cannot divide by zero"
        return a / b
    else:
        return "Invalid operation"

