def find_odd_occurrence(arr):
    """
    Returns an integer that occurs an odd number of times in the list.
    If no such integer exists, returns None.
    """
    count = {}
    for num in arr:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    for num, cnt in count.items():
        if cnt % 2 != 0:
            return num

    return None

```

