import json


def calc_avg_grades(students):
    """
    Calculate the average grade for each student and return a JSON-formatted string.

    :param students: List of dictionaries, each containing 'name' and 'grades'.
    :return: JSON-formatted string with each student's name and their average grade.
    """
    averages = {}
    for student in students:
        name = student["name"]
        grades = student["grades"]
        if grades:
            avg_grade = round(sum(grades) / len(grades), 2)
        else:
            avg_grade = None
        averages[name] = avg_grade
    return json.dumps(averages)

