def manage_stock(current_stock, new_shipments):
    """
    Updates the current stock with new shipment quantities.

    Args:
    current_stock (list): A list of dictionaries representing the current stock.
    new_shipments (list): A list of dictionaries representing the new shipments.

    Returns:
    dict: A dictionary with updated stock quantities.
    """
    stock = {}

    # Consolidate current stock into a single dictionary
    for item in current_stock:
        for product, quantity in item.items():
            if product in stock:
                stock[product] += quantity
            else:
                stock[product] = quantity

    # Add new shipments to the consolidated stock
    for shipment in new_shipments:
        for product, quantity in shipment.items():
            if product in stock:
                stock[product] += quantity
            else:
                stock[product] = quantity

    return stock

```

