def calculate_averages(student_scores):
    """
    Takes a list of tuples with student names and their scores, and returns a dictionary
    mapping each student's name to their average score.
    """
    score_dict = {}
    count_dict = {}

    for name, score in student_scores:
        if name not in score_dict:
            score_dict[name] = 0
            count_dict[name] = 0
        score_dict[name] += score
        count_dict[name] += 1

    average_dict = {name: score_dict[name] / count_dict[name] for name in score_dict}

    return average_dict

```

