def average_temperature(data):
    """
    This function takes a list of dictionaries containing temperature data per city
    and returns a dictionary with the average temperature for each city.
    """
    temp_sum = {}
    temp_count = {}

    for entry in data:
        city = entry["City"]
        temperature = entry["Temperature"]

        if city in temp_sum:
            temp_sum[city] += temperature
            temp_count[city] += 1
        else:
            temp_sum[city] = temperature
            temp_count[city] = 1

    average_temp = {}
    for city in temp_sum:
        average_temp[city] = temp_sum[city] / temp_count[city]

    return average_temp

```

