def reverse_words(s):
    """
    Reverses each word in a given string s while maintaining the word order.

    Parameters:
    s (str): The input sentence string.

    Returns:
    str: A new string with each word reversed.
    """
    result = []
    word = []

    for char in s:
        if char != ' ':
            word.append(char)
        else:
            while word:
                result.append(word.pop())
            result.append(' ')
    while word:
        result.append(word.pop())

    return ''.join(result)

