def update_inventory(stock: dict, transactions: list) -> dict:
    """
    Updates the stock levels based on a list of transactions.

    Parameters:
        stock (dict): A dictionary where keys are product categories and values are their stock levels.
        transactions (list): A list of tuples, where each tuple consists of (category, operation, quantity).

    Returns:
        dict: The updated stock levels.
    """
    for category, operation, quantity in transactions:
        if category in stock:
            if operation == 'add':
                stock[category] += quantity
            elif operation == 'remove':
                stock[category] = max(stock[category] - quantity, 0)
        else:
            if operation == 'add':
                stock[category] = quantity
            elif operation == 'remove':
                stock[category] = 0  # If the category does not exist, removing results in 0 stock

    return stock

```

