```python
def fib(n: int) -> int:
    """
    Returns the n-th Fibonacci number using memoization
    """
    memo = {0: 0, 1: 1}

    def helper(x):
        if x not in memo:
            memo[x] = helper(x - 1) + helper(x - 2)
        return memo[x]

    return helper(n)

```

