def generate_subsequences(s: str) -> list:
    """
    Returns all unique subsequences of the input string in lexicographical order.
    """
    def subsequences_helper(s):
        if not s:
            return {""}

        smaller_subsequences = subsequences_helper(s[1:])
        combined_subsequences = {s[0] + sub for sub in smaller_subsequences}

        return smaller_subsequences | combined_subsequences

    return sorted(list(subsequences_helper(s)))

```

