def alphabetical_sort(titles: list[str]) -> list[str]:
    """
    Sorts a list of book titles in alphabetical order using the merge sort algorithm.

    :param titles: A list of strings, where each string is a book title.
    :return: The sorted list of book titles in alphabetical order.
    """

    def merge(left: list[str], right: list[str]) -> list[str]:
        sorted_list = []
        while left and right:
            if left[0].lower() <= right[0].lower():
                sorted_list.append(left.pop(0))
            else:
                sorted_list.append(right.pop(0))
        sorted_list.extend(left or right)
        return sorted_list

    def merge_sort(titles: list[str]) -> list[str]:
        if len(titles) <= 1:
            return titles
        mid = len(titles) // 2
        left = merge_sort(titles[:mid])
        right = merge_sort(titles[mid:])
        return merge(left, right)

    return merge_sort(titles)

```

