def calculate_inventory(operations):
    """
    Returns a dictionary with the total count of each item in the inventory.
    """
    inventory = {}

    for item_id, count in operations:
        if item_id not in inventory:
            inventory[item_id] = 0
        inventory[item_id] += count

    return inventory

```

