def sort_dict_values_desc(input_dict):
    """
    Takes a dictionary with string keys and list of integers as values, 
    and returns a new dictionary with the same keys, where each integer list 
    is sorted in descending order if the list contains 3 or more integers.
    """
    output_dict = {}
    for key, value in input_dict.items():
        if len(value) >= 3:
            output_dict[key] = sorted(value, reverse=True)
        else:
            output_dict[key] = value
    return output_dict

```

