def char_frequency(s):
    """
    Returns a dictionary with characters that appear more than once in the string s
    and their frequency of occurrence.
    """
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    return {char: count for char, count in frequency.items() if count > 1}

