def find_char_frequencies(text):
    """
    Returns a dictionary with the frequency of each character in the string.
    Ignore whitespaces and consider all characters as lowercase.
    """
    text = text.replace(" ", "").lower()
    freq_dict = {}

    for char in text:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1

    return freq_dict

