def valid_bracket_sequence(s):
    """
    Determine whether the given string s is a valid sequence of brackets.

    :param s: String composed of brackets '()', '[]', '{}'
    :return: True if the sequence is valid, False otherwise
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or bracket_map[char] != stack.pop():
                return False
        else:
            # Invalid character
            return False

    return not stack

```

