def valid_parentheses(s):
    """
    Function to check if a string of parentheses is valid.
    A string is valid if all open brackets are closed by the same type of brackets in the correct order.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if stack == [] or mapping[char] != stack.pop():
                return False
    return stack == []

```

