def filter_strings_by_id(data, provided_id):
    """
    Returns a list of strings that match the provided ID and meet the requirements:
    - Contain only lowercase letters
    - Do not contain any special characters
    """
    def is_valid_string(s):
        return s.isalpha() and s.islower()

    result = []
    for item in data:
        if item['id'] == provided_id:
            result.extend([s for s in item['characters'] if is_valid_string(s)])

    return result

```

