def sum_arithmetic_series(start, difference, stop, divisor):
    """
    Recursively calculates the sum of an arithmetic series that starts with 'start',
    increases by 'difference' and goes up to 'stop'. The sum should include
    only those terms that are divisible by 'divisor'.
    """
    # Base case: If start exceeds stop, end the recursion
    if start > stop:
        return 0

    # If start is divisible by divisor, include it in the sum
    if start % divisor == 0:
        return start + sum_arithmetic_series(start + difference, difference, stop, divisor)
    else:
        return sum_arithmetic_series(start + difference, difference, stop, divisor)

```

