def reverse_and_remove_duplicates(lst):
    """
    Reverses the elements of the list using recursion and removes duplicates.
    """
    def reverse_helper(lst, seen):
        if not lst:
            return []
        head, *tail = lst
        if head not in seen:
            return reverse_helper(tail, seen | {head}) + [head]
        return reverse_helper(tail, seen)

    return reverse_helper(lst, set())

```

