def count_char_types(input_str):
    """
    Returns a dictionary with counts of each specified character type: 'digit', 'upper', 'lower' and 'space'.
    """
    char_types = ['digit', 'upper', 'lower', 'space']
    counts = {ctype: 0 for ctype in char_types}

    for char in input_str:
        if char.isdigit():
            counts['digit'] += 1
        if char.isupper():
            counts['upper'] += 1
        if char.islower():
            counts['lower'] += 1
        if char.isspace():
            counts['space'] += 1

    return counts

