def first_three_unique_indices(arr):
    """
    Returns the indices of the first three unique elements in the array.
    If there are fewer than three unique elements, return the indices of however many unique elements are present.
    """
    unique_indices = {}

    for index, value in enumerate(arr):
        if value not in unique_indices:
            unique_indices[value] = index
        if len(unique_indices) == 3:
            break

    return list(unique_indices.values())

