def max_distance(arr):
    """
    Returns the maximum distance between two same elements of the list arr.
    """
    if not arr:
        return 0

    index_map = {}
    max_dist = 0

    for idx, value in enumerate(arr):
        if value in index_map:
            max_dist = max(max_dist, idx - index_map[value])
        else:
            index_map[value] = idx

    return max_dist

```

