def count_characters(s):
    """
    Count the number of letters, digits, and other characters in the string s.

    Args:
    s (str): The input string.

    Returns:
    dict: A dictionary with keys 'letters', 'digits', and 'others' and their respective counts.
    """
    counts = {'letters': 0, 'digits': 0, 'others': 0}

    for char in s:
        if char.isalpha():
            counts['letters'] += 1
        elif char.isdigit():
            counts['digits'] += 1
        else:
            counts['others'] += 1

    return counts

```

