```python
import cmath


def find_roots(a, b, c):
    """
    Returns the roots of the quadratic equation ax^2 + bx + c = 0.
    If the equation has no real roots, returns ("No real roots",).
    """
    if a == 0:
        return ("Invalid equation, not a quadratic equation",)

    # Calculate the discriminant
    discriminant = b**2 - 4*a*c

    # Discriminant determines the nature of the roots
    if discriminant > 0:
        # Two distinct real roots
        root1 = (-b + cmath.sqrt(discriminant)) / (2*a)
        root2 = (-b - cmath.sqrt(discriminant)) / (2*a)
        return (root1.real, root2.real)
    elif discriminant == 0:
        # One real root, a perfect square trinomial
        root = -b / (2*a)
        return (root,)
    else:
        # No real roots
        return ("No real roots",)

```

