import re


def simple_math_chatbot(input_text):
    """
    This function takes a user input as a string, identifies the math operation
    and numbers, and returns the result of the computation.

    Supported operations are: addition, subtraction, multiplication, division.
    """
    # Define regex patterns for operations
    patterns = {
        'add': r'(\d+)\s*\+\s*(\d+)',
        'subtract': r'(\d+)\s*-\s*(\d+)',
        'multiply': r'(\d+)\s*\*\s*(\d+)',
        'divide': r'(\d+)\s*/\s*(\d+)'
    }

    for operation, pattern in patterns.items():
        match = re.search(pattern, input_text)
        if match:
            num1, num2 = int(match.group(1)), int(match.group(2))
            if operation == 'add':
                return num1 + num2
            elif operation == 'subtract':
                return num1 - num2
            elif operation == 'multiply':
                return num1 * num2
            elif operation == 'divide':
                if num2 != 0:
                    return num1 / num2
                else:
                    return "Error: Division by zero"

    return "Error: Unsupported operation"

```

