```python
def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries. If they have the same keys, append the values into a list.
    If a key appears in only one dictionary, keep its value as is.

    :param dict1: First dictionary
    :param dict2: Second dictionary
    :return: Merged dictionary
    """
    merged_dict = {}

    # Add keys from the first dictionary
    for key in dict1:
        if key in dict2:
            if not isinstance(dict1[key], list):
                dict1[key] = [dict1[key]]
            if not isinstance(dict2[key], list):
                dict2[key] = [dict2[key]]

            merged_dict[key] = dict1[key] + dict2[key]
        else:
            merged_dict[key] = dict1[key]

    # Add keys from the second dictionary that are not in the first dictionary
    for key in dict2:
        if key not in dict1:
            merged_dict[key] = dict2[key]

    return merged_dict

```

