def nested_dict_from_flat(flat_dict, delimiter='.'):
    """
    Converts a flat dictionary with nested keys into a nested dictionary.

    :param flat_dict: flat dictionary with nested keys
    :param delimiter: delimiter used in the keys to indicate nesting (default is '.')
    :return: a nested dictionary
    """
    nested_dict = {}

    for key, value in flat_dict.items():
        parts = key.split(delimiter)
        d = nested_dict
        for part in parts[:-1]:
            if part not in d:
                d[part] = {}
            d = d[part]
        d[parts[-1]] = value

    return nested_dict

```

