def sum_of_digits(n):
    """
    Returns the sum of the digits of a given number n using recursion.
    """
    # Base case: if n is a single digit, return n
    if n < 10:
        return n
    else:
        # Recursively sum the last digit and the sum of the digits of the remaining number
        return n % 10 + sum_of_digits(n // 10)

```

