import string


def word_count(lst):
    """
    Returns a dictionary where the keys are unique words and values are counts of those words.
    The function handles punctuation and is case-insensitive.
    """
    word_dict = {}

    for sentence in lst:
        # Remove punctuation and convert to lowercase
        words = sentence.translate(str.maketrans('', '', string.punctuation)).lower().split()

        for word in words:
            if word in word_dict:
                word_dict[word] += 1
            else:
                word_dict[word] = 1

    return word_dict

```

