def count_character_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the string `s`, ignoring case sensitivity.
    """
    frequency = {}
    s = s.lower()

    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    return frequency

