import string


def word_count(words_list):
    """
    Returns a dictionary with unique words as keys and their counts as values.
    """
    word_count_dict = {}
    translator = str.maketrans('', '', string.punctuation)
    for word in words_list:
        clean_word = word.lower().translate(translator)
        if clean_word:
            if clean_word in word_count_dict:
                word_count_dict[clean_word] += 1
            else:
                word_count_dict[clean_word] = 1
    return word_count_dict

```

