def list_of_dicts_to_dict_of_lists(lst):
    """
    Converts a list of dictionaries into a dictionary of lists.

    Parameters:
    lst (list of dict): List of dictionaries to be converted.

    Returns:
    dict: A dictionary with keys from the input dictionaries and values as lists of corresponding values.
    """
    if not lst:
        return {}

    result = {}
    for d in lst:
        for key, value in d.items():
            if key not in result:
                result[key] = []
            result[key].append(value)
    return result

```

