def count_consecutive_characters(s):
    """
    Returns a string with each character and its consecutive count.
    For example: input "AAAABBBCCCDDDD" will return "A4B3C3D4".
    """
    if not s:
        return ""

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(s[i - 1] + str(count))
            count = 1

    result.append(s[-1] + str(count))

    return ''.join(result)

```

