def char_frequency(s: str) -> dict:
    """
    Returns a frequency count of each alphanumeric character in the given string,
    ignoring case and excluding spaces or special characters.
    """
    s = ''.join(filter(str.isalnum, s.lower()))
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    return freq

```

