def merge_dicts(dict_list):
    """
    Merges a list of dictionaries into a single dictionary. Collates values into lists for duplicate keys.

    Parameters:
        dict_list (list): A list of dictionaries to be merged.

    Returns:
        dict: A single dictionary with all the keys from the input dictionaries.
              For duplicate keys, the values appear as lists in the same order as they appeared in dict_list.
    """
    merged_dict = {}

    for d in dict_list:
        for key, value in d.items():
            if key in merged_dict:
                if isinstance(merged_dict[key], list):
                    merged_dict[key].append(value)
                else:
                    merged_dict[key] = [merged_dict[key], value]
            else:
                merged_dict[key] = value

    # Ensure all values are lists
    for key in merged_dict:
        if not isinstance(merged_dict[key], list):
            merged_dict[key] = [merged_dict[key]]

    return merged_dict

```

