from typing import List


def smooth_sequence(arr: List[int]) -> List[float]:
    """
    Computes the moving average of the input list of integers.
    """
    if len(arr) == 1:
        return [float(arr[0])]

    result = []
    for i in range(len(arr)):
        if i == 0:
            avg = (arr[i] + arr[i + 1]) / 2
        elif i == len(arr) - 1:
            avg = (arr[i] + arr[i - 1]) / 2
        else:
            avg = (arr[i - 1] + arr[i] + arr[i + 1]) / 3
        result.append(avg)
    return result

```

