from typing import List


def zero_matrix(matrix: List[List[int]]) -> None:
    """
    Takes a 2D matrix and sets the entire row and column to 0 if an element is 0.
    Modifies the matrix in place.
    """
    if not matrix or not matrix[0]:
        return

    rows = len(matrix)
    cols = len(matrix[0])

    zero_rows = set()
    zero_cols = set()

    # First pass: identify all rows and columns that need to be zeroed
    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 0:
                zero_rows.add(i)
                zero_cols.add(j)

    # Second pass: set the necessary rows and columns to zero
    for i in zero_rows:
        for j in range(cols):
            matrix[i][j] = 0

    for j in zero_cols:
        for i in range(rows):
            matrix[i][j] = 0

