def evaluate_rpn(tokens: list[str]) -> float:
    """
    Evaluate a mathematical expression in Reverse Polish Notation (RPN).

    Args:
        tokens (list): List of tokens representing the RPN expression.

    Returns:
        float: The evaluation result of the RPN expression.
    """
    stack = []

    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                stack.append(a / b)
        else:
            stack.append(float(token))

    return stack.pop()

```

