def flatten_dict(input_dict):
    """
    Flattens a dictionary where the values are lists of tuples containing a string and an integer,
    and returns a new dictionary with the strings as keys and the sum of their integers as values.
    """
    result = {}
    for key in input_dict:
        for item in input_dict[key]:
            str_key, val = item
            if str_key in result:
                result[str_key] += val
            else:
                result[str_key] = val
    return result

```

