def convert_temperature(value: float, scale: str) -> dict:
    """
    Convert the given temperature `value` from the `scale` to the other two scales.

    Parameters:
    value (float): The temperature to be converted.
    scale (str): The scale of the input temperature ('C', 'F', or 'K').

    Returns:
    dict: A dictionary with keys 'C', 'F', 'K' containing the converted temperatures.
    """
    if scale not in ('C', 'F', 'K'):
        raise ValueError("Invalid scale: scale must be 'C', 'F', or 'K'")

    if scale == 'C':
        F = value * 9/5 + 32
        K = value + 273.15
        return {'F': F, 'K': K}

    elif scale == 'F':
        C = (value - 32) * 5/9
        K = C + 273.15
        return {'C': C, 'K': K}

    elif scale == 'K':
        C = value - 273.15
        F = C * 9/5 + 32
        return {'C': C, 'F': F}

```

