def generate_fibonacci_terms(n):
    """
    Generates the first n terms of the Fibonacci sequence using memoization.

    :param n: The number of terms to generate.
    :return: A list of the first n terms of the Fibonacci sequence.
    """
    if n == 0:
        return []
    if n == 1:
        return [0]

    memo = {0: 0, 1: 1}

    def fib(k):
        if k not in memo:
            memo[k] = fib(k-1) + fib(k-2)
        return memo[k]

    fib_sequence = [fib(i) for i in range(n)]
    return fib_sequence

```

