def is_palindrome_substring(s: str, min_length: int) -> bool:
    """
    Determines if there exists at least one palindromic substring of length 
    greater than or equal to the specified minimum length in the given string.
    """
    def is_palindrome(sub: str) -> bool:
        return sub == sub[::-1]

    n = len(s)
    for i in range(n):
        for j in range(i + min_length, n + 1):
            if is_palindrome(s[i:j]):
                return True
    return False

```

