def get_primes(n):
    """
    Returns a list of the first n prime numbers.
    """
    if n < 1:
        return []

    primes = []
    candidate = 2
    while len(primes) < n:
        for p in primes:
            if p * p > candidate:
                primes.append(candidate)
                break
            if candidate % p == 0:
                break
        else:
            primes.append(candidate)
        candidate += 1
    return primes

```

