def increment_numbers_in_string(s):
    """
    Given a string s, this function returns the string with all numbers incremented by 1
    (9 should become 0), while leaving other characters unchanged.

    If the input is not a string, it returns a message indicating invalid input.
    """
    if not isinstance(s, str):
        return "Invalid input, expected a string."

    def increment_char(c):
        if c.isdigit():
            return str((int(c) + 1) % 10)
        return c

    return ''.join(increment_char(c) for c in s)

```

