def is_balanced(s):
    """
    Validates that the string s containing only the characters '(', ')',
    '{', '}', '[' and ']' is a balanced sequence of parentheses, braces, and brackets.
    """
    stack = []
    matching_pairs = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_pairs.values():
            # If the character is one of '(', '{', '[' push it to stack
            stack.append(char)
        elif char in matching_pairs:
            # If the character is one of ')', '}', ']' check for matching
            if stack and stack[-1] == matching_pairs[char]:
                stack.pop()
            else:
                return False
        else:
            return False  # invalid character

    return len(stack) == 0

```

