def greatest_difference(nums):
    """
    Returns the greatest difference between any two numbers in the list
    using a divide-and-conquer algorithm.
    """
    def helper(nums, left, right):
        if left == right:
            return (nums[left], nums[left])

        mid = (left + right) // 2
        left_min, left_max = helper(nums, left, mid)
        right_min, right_max = helper(nums, mid + 1, right)

        return (min(left_min, right_min), max(left_max, right_max))

    if not nums:
        return 0

    min_value, max_value = helper(nums, 0, len(nums) - 1)
    return max_value - min_value

```

