def replace_vowels_with_next(s):
    """
    Replaces each vowel in the input string with the next vowel in sequence.

    Parameters:
    s (str): The input string

    Returns:
    str: The string with each vowel replaced by the next vowel in sequence
    """
    next_vowel = {'a': 'e', 'e': 'i', 'i': 'o', 'o': 'u', 'u': 'a', 'A': 'E', 'E': 'I', 'I': 'O', 'O': 'U', 'U': 'A'}
    result = []

    for char in s:
        if char in next_vowel:
            result.append(next_vowel[char])
        else:
            result.append(char)

    return ''.join(result)

```

