def find_first_and_last_occurrence(lst, target):
    """
    Returns the first and last occurrence of a target integer in a list.
    If the target is not found, return (-1, -1).
    """
    first_occurrence = -1
    last_occurrence = -1

    for i in range(len(lst)):
        if lst[i] == target:
            if first_occurrence == -1:
                first_occurrence = i
            last_occurrence = i

    return (first_occurrence, last_occurrence)

```

