def collapse_duplicates(s):
    """
    Returns a version of the string `s` with all consecutive duplicate characters collapsed into a single character.
    """
    if not s:
        return ""

    collapsed_string = [s[0]]

    for char in s[1:]:
        if char != collapsed_string[-1]:
            collapsed_string.append(char)

    return ''.join(collapsed_string)

```

