def count_chars(input_str):
    """
    Counts the number of uppercase letters, lowercase letters, and digits in the input string.

    :param input_str: The input string to be analyzed.
    :return: A dictionary with keys 'uppercase', 'lowercase', and 'digits' corresponding to their respective counts.
    """
    counts = {'uppercase': 0, 'lowercase': 0, 'digits': 0}

    for char in input_str:
        if char.isupper():
            counts['uppercase'] += 1
        elif char.islower():
            counts['lowercase'] += 1
        elif char.isdigit():
            counts['digits'] += 1

    return counts

```

