def search_value_in_json(json_obj, target_value):
    """
    Searches for a specific value within a nested JSON structure.

    :param json_obj: JSON object (can be a dictionary or list)
    :param target_value: The value to search for
    :return: True if the value is found, False otherwise
    """
    if isinstance(json_obj, dict):
        for key, value in json_obj.items():
            if search_value_in_json(value, target_value):
                return True
    elif isinstance(json_obj, list):
        for item in json_obj:
            if search_value_in_json(item, target_value):
                return True
    else:
        if json_obj == target_value:
            return True
    return False

```

