def determine_type(var):
    """
    Determine the type of variable without using built-in functions like type().
    Only supports int, float, str, list, dict, bool types.
    """
    if (isinstance(var, bool)):
        # Booleans are also instances of integers in Python.
        return "bool"
    elif (isinstance(var, int)):
        return "int"
    elif (isinstance(var, float)):
        return "float"
    elif (isinstance(var, str)):
        return "str"
    elif (isinstance(var, list)):
        return "list"
    elif (isinstance(var, dict)):
        return "dict"
    else:
        return "unknown"

```

