def shift_letters(s):
    """
    This function takes a string as input and returns a new string 
    where each character has been replaced with the character that follows it in the alphabet.
    """
    shifted_string = ""
    for char in s:
        if char.isalpha():
            if char == 'z':
                shifted_string += 'a'
            elif char == 'Z':
                shifted_string += 'A'
            else:
                shifted_string += chr(ord(char) + 1)
        else:
            shifted_string += char
    return shifted_string

