def transform_string(s):
    """
    Returns a new string where all the letters are converted to uppercase,
    all the digits are left unchanged, and any spaces are removed.
    """
    result = []
    for char in s:
        if char.isalpha():
            result.append(char.upper())
        elif char.isdigit():
            result.append(char)
        elif char == " ":
            continue
        else:
            result.append(char)
    return ''.join(result)

```

