def find_pair(nums, target):
    """
    Finds the first pair of elements in an unsorted array that sum to a given target.
    """
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [nums[i], nums[j]]
    return []

```

