def merge_dicts(dict_list):
    """
    Merges a list of dictionaries, summing values of identical keys.

    Args:
    dict_list: List of dictionaries to merge.

    Returns:
    A single dictionary with all keys from input dictionaries and summed values.
    """
    result = {}

    for dictionary in dict_list:
        for key, value in dictionary.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value

    return result

```

