def process_transactions(transactions: list, initial_balance: float) -> float:
    """
    Processes a list of transactions and returns the final account balance.
    """
    balance = initial_balance
    for transaction in transactions:
        if transaction["type"] == "deposit":
            balance += transaction["amount"]
        elif transaction["type"] == "withdrawal":
            if transaction["amount"] <= balance:
                balance -= transaction["amount"]
        else:
            raise ValueError(f"Unknown transaction type: {transaction['type']}")

    return balance

```

