```python
from typing import List


def title_case(text: str, small_words: List[str]) -> str:
    """
    Converts a given text string to title case according to the rules,
    where small words remain lowercase unless they're the first or last word.
    """
    if not text:
        return ""

    words = text.split()
    title_cased_words = []

    for idx, word in enumerate(words):
        if idx == 0 or idx == len(words) - 1 or word.lower() not in small_words:
            title_cased_words.append(word.capitalize())
        else:
            title_cased_words.append(word.lower())

    return " ".join(title_cased_words)

```

