def count_unique_elements(data):
    """
    Recursively counts the frequency of unique elements in a nested list or dictionary.
    """
    freq_dict = {}

    def count_elements(elem):
        if isinstance(elem, (int, float, str)):
            if elem in freq_dict:
                freq_dict[elem] += 1
            else:
                freq_dict[elem] = 1
        elif isinstance(elem, list):
            for item in elem:
                count_elements(item)
        elif isinstance(elem, dict):
            for key, value in elem.items():
                count_elements(key)
                count_elements(value)

    count_elements(data)
    return freq_dict

```

