def rle_compress(s: str) -> str:
    """
    Compresses a given string `s` using the Run-Length Encoding (RLE) algorithm.

    Args:
    s (str): The string to be compressed.

    Returns:
    str: The Run-Length Encoded string.
    """
    if not s:
        return ""

    compressed = []
    count = 1
    prev_char = s[0]

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            if count > 1:
                compressed.append(f"{prev_char}{count}")
            else:
                compressed.append(prev_char)
            prev_char = char
            count = 1

    if count > 1:
        compressed.append(f"{prev_char}{count}")
    else:
        compressed.append(prev_char)

    return ''.join(compressed)

```

