```python
from typing import List


def find_peak_element(arr: List[int]) -> int:
    """
    Finds the index of a peak element in the list.

    A peak element is defined as an element that is greater than its neighbors. 
    Boundaries of the list count as negative infinity.

    :param arr: List of integers
    :return: Index of a peak element
    """
    n = len(arr)

    def binary_search(low: int, high: int) -> int:
        if low == high:
            return low
        mid = (low + high) // 2

        if arr[mid] > arr[mid + 1]:
            return binary_search(low, mid)
        else:
            return binary_search(mid + 1, high)

    return binary_search(0, n - 1)

```

