def longest_consecutive_sublist(lst):
    """
    Returns the longest sublist of consecutive integers present in the list.
    """
    if not lst:
        return []

    lst = sorted(set(lst))
    longest_sublist = []
    current_sublist = [lst[0]]

    for i in range(1, len(lst)):
        if lst[i] == lst[i-1] + 1:
            current_sublist.append(lst[i])
        else:
            if len(current_sublist) > len(longest_sublist):
                longest_sublist = current_sublist
            current_sublist = [lst[i]]

    if len(current_sublist) > len(longest_sublist):
        longest_sublist = current_sublist

    return longest_sublist

```

