def compare_lists_ignore_order(list1, list2):
    """
    Compares two lists for equality of elements, disregarding the order.
    Handles lists with non-hashable items like dictionaries or other lists.
    """
    if len(list1) != len(list2):
        return False

    def to_sorted_tuple(item):
        if isinstance(item, list):
            return tuple(to_sorted_tuple(i) for i in sorted(item, key=lambda x: (str(type(x)), str(x))))
        elif isinstance(item, dict):
            return tuple(sorted((k, to_sorted_tuple(v)) for k, v in item.items()))
        return item

    sorted_list1 = sorted((to_sorted_tuple(item) for item in list1), key=lambda x: (str(type(x)), str(x)))
    sorted_list2 = sorted((to_sorted_tuple(item) for item in list2), key=lambda x: (str(type(x)), str(x)))

    return sorted_list1 == sorted_list2

```

