def check_iterable(arg):
    """
    Checks if the argument is iterable.
    If it's a list, returns ('list', count of dictionaries inside the list).
    If it's a dictionary, returns ('dictionary', all keys of the dictionary).
    If it's neither, returns 'non-iterable'.
    """
    if isinstance(arg, list):
        count_dicts = sum(isinstance(item, dict) for item in arg)
        return ('list', count_dicts)
    elif isinstance(arg, dict):
        return ('dictionary', list(arg.keys()))
    else:
        return 'non-iterable'

```

