def check_variable_type(x):
    """
    Returns the type of the variable x as a string. 
    Specifically identifies int, float, str, list, tuple, dict, and set.
    Returns "Unknown Type" for any other type.
    """
    if isinstance(x, int):
        return "int"
    elif isinstance(x, float):
        return "float"
    elif isinstance(x, str):
        return "str"
    elif isinstance(x, list):
        return "list"
    elif isinstance(x, tuple):
        return "tuple"
    elif isinstance(x, dict):
        return "dict"
    elif isinstance(x, set):
        return "set"
    else:
        return "Unknown Type"

```

