def average_of_string_numbers(lst):
    """
    Calculate the average of a list of strings that represent numbers. Non-numeric strings are ignored.

    Args:
    - lst (list of str): List of strings representing numbers.

    Returns:
    - float: Average of the numeric values as a float. Returns 0.0 if the list is empty or contains only non-numeric strings.
    """
    numeric_values = []

    for item in lst:
        try:
            numeric_values.append(float(item))
        except ValueError:
            continue

    if not numeric_values:
        return 0.0

    return sum(numeric_values) / len(numeric_values)

```

