import bisect


def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest increasing subsequence in the given array using O(n log n) approach.
    """
    if not arr:
        return 0

    subseq = []

    for num in arr:
        pos = bisect.bisect_left(subseq, num)
        if pos == len(subseq):
            subseq.append(num)
        else:
            subseq[pos] = num

    return len(subseq)

```

