def sum_mixed_list(mixed_list):
    """
    Sums the values in a mixed list.

    Parameters:
        mixed_list (list): The list containing mixed types.

    Returns:
        int: The sum of the values.
    """
    total_sum = 0

    for item in mixed_list:
        if isinstance(item, (int, float)):
            total_sum += item
        elif isinstance(item, list):
            total_sum += sum_mixed_list(item)
        elif isinstance(item, tuple):
            total_sum += sum(item)
        elif isinstance(item, set):
            total_sum += sum(item)
        elif isinstance(item, dict):
            total_sum += sum(item.values())
        elif isinstance(item, str):
            total_sum += sum(ord(char) for char in item)

    return total_sum

```

