def length_of_LNDS(sequence):
    """
    Returns the length of the longest non-decreasing subsequence in the given sequence.
    :param sequence: list of integers
    :return: integer length of the longest non-decreasing subsequence
    """
    if not sequence:
        return 0

    n = len(sequence)
    dp = [1] * n  # dp[i] will be the length of LNDS ending at i

    for i in range(1, n):
        for j in range(i):
            if sequence[i] >= sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

```

