def min_bracket_insertions(expr: str) -> int:
    """Returns the minimum number of bracket insertions needed to balance the expression."""
    open_brackets = 0
    insertions_needed = 0

    for char in expr:
        if char == '(':
            open_brackets += 1
        elif char == ')':
            if open_brackets > 0:
                open_brackets -= 1
            else:
                insertions_needed += 1

    # Add the remaining open brackets to the insertions needed
    insertions_needed += open_brackets

    return insertions_needed

```

