def example_goto_simulation(value):
    """
    Simulates a goto-like mechanism in Python using a loop and dictionary.
    """
    labels = {
        "start": 1,
        "check": 2,
        "middle": 3,
        "end": 4
    }

    current_position = labels["start"]

    while True:
        if current_position == labels["start"]:
            current_position = labels["check"]  # Go to "check"

        elif current_position == labels["check"]:
            if value < 10:
                current_position = labels["middle"]  # Go to "middle"
            else:
                current_position = labels["end"]  # Go to "end"

        elif current_position == labels["middle"]:
            return "Value is less than 10"  # Exit from "middle"

        elif current_position == labels["end"]:
            return "Value is 10 or greater"

