def categorize_grades(students):
    """
    Categorizes students into grade categories based on their grades.

    Parameters:
    students (list of tuples): A list where each tuple contains a student's name and their grade (0-100).

    Returns:
    dict: A dictionary with grade categories ('A', 'B', 'C', 'D', 'F') as keys and lists of student names as values.
    """
    grade_categories = { 
        'A': [], 
        'B': [], 
        'C': [], 
        'D': [], 
        'F': [] 
    }

    for name, grade in students:
        if not isinstance(grade, int) or not 0 <= grade <= 100:
            continue  # Skip invalid grades

        if grade >= 90:
            grade_categories['A'].append(name)
        elif grade >= 80:
            grade_categories['B'].append(name)
        elif grade >= 70:
            grade_categories['C'].append(name)
        elif grade >= 60:
            grade_categories['D'].append(name)
        else:
            grade_categories['F'].append(name)

    return grade_categories

```

