def edit_sequence(s1, s2):
    """
    Returns the sequence of edits needed to transform s1 to s2 by removing, inserting, or replacing one character.
    """
    n, m = len(s1), len(s2)
    if n == m:
        # Replacement case
        edits = []
        for i in range(n):
            if s1[i] != s2[i]:
                edits.append(f"r({s1[i]}->{s2[i]})")
        if len(edits) == 0:
            return "No edit needed"
        return min(edits)
    elif n < m:
        # Insertion case
        for i in range(n):
            if s1[i] != s2[i]:
                return f"i({s2[i]})"
        return f"i({s2[n]})"
    else:
        # Removal case
        for i in range(m):
            if s1[i] != s2[i]:
                return f"d({s1[i]})"
        return f"d({s1[m]})"

