import json


def compare_json(json1, json2, path=""):
    """
    Compare two JSON objects and return a list of differences.

    :param json1: First JSON object (dict).
    :param json2: Second JSON object (dict).
    :param path: Path for tracking the differences (used for recursion).
    :return: List of differences.
    """
    differences = []

    if isinstance(json1, str):
        json1 = json.loads(json1)
    if isinstance(json2, str):
        json2 = json.loads(json2)

    # Compare keys and values
    for key in json1:
        new_path = f"{path}/{key}" if path else key
        if key not in json2:
            differences.append(f"Key {new_path} is missing in the second JSON object.")
        else:
            if isinstance(json1[key], dict) and isinstance(json2[key], dict):
                differences.extend(compare_json(json1[key], json2[key], new_path))
            elif json1[key] != json2[key]:
                differences.append(f"Value at {new_path} differs: {json1[key]} != {json2[key]}")

    for key in json2:
        new_path = f"{path}/{key}" if path else key
        if key not in json1:
            differences.append(f"Key {new_path} is missing in the first JSON object.")

    return differences

