def infix_to_postfix(expression: str) -> str:
    """Convert infix expression string to postfix expression string."""
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    stack = []

    def is_operator(c):
        return c in precedence

    def precedence_of(c):
        return precedence[c] if c in precedence else 0

    def handle_operator(op):
        while stack and precedence_of(op) <= precedence_of(stack[-1]):
            output.append(stack.pop())
        stack.append(op)

    tokens = expression.split()
    for token in tokens:
        if token.isalnum():  # Operand
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # pop '('
        elif is_operator(token):
            handle_operator(token)

    while stack:
        output.append(stack.pop())

    return ' '.join(output)

