def evaluate_expression(expression: str) -> float:
    """
    Evaluates a simple mathematical expression.
    """
    import re

    # Tokenize the expression
    def tokenize(expression):
        tokens = re.findall(r'\d+\.\d+|\d+|[+*/()-]', expression)
        return tokens

    # Parse tokens based on precedence
    def parse(tokens):
        def parse_expression(index):
            current = parse_term(index)
            while index[0] < len(tokens) and tokens[index[0]] in ('+', '-'):
                op = tokens[index[0]]
                index[0] += 1
                next_term = parse_term(index)
                if op == '+':
                    current += next_term
                elif op == '-':
                    current -= next_term
            return current

        def parse_term(index):
            current = parse_factor(index)
            while index[0] < len(tokens) and tokens[index[0]] in ('*', '/'):
                op = tokens[index[0]]
                index[0] += 1
                next_factor = parse_factor(index)
                if op == '*':
                    current *= next_factor
                elif op == '/':
                    current /= next_factor
            return current

        def parse_factor(index):
            current = None
            if index[0] < len(tokens) and tokens[index[0]] == '(':
                index[0] += 1
                current = parse_expression(index)
                index[0] += 1  # Skipping ')'
            else:
                current = float(tokens[index[0]])
                index[0] += 1
            return current

        index = [0]
        return parse_expression(index)

    tokens = tokenize(expression)
    return parse(tokens)

```

