def compute_average(numbers, weights=None):
    """
    Computes the average of a list of positive integers.
    Optionally calculates the weighted average if weights are provided.

    :param numbers: List of positive integers
    :param weights: Optional list of weights as floats or integers
    :return: Average or weighted average as a floating-point number
    """
    if not all(isinstance(n, int) and n > 0 for n in numbers):
        return "Error: List must contain only positive integers."

    if weights is not None:
        if len(weights) != len(numbers):
            return "Error: The number of weights must match the number of numbers."
        if not all(isinstance(w, (int, float)) for w in weights):
            return "Error: All weights must be integers or floats."
        if not abs(sum(weights) - 1.0) < 1e-6:
            return "Error: Weights must sum up to 1."

        weighted_sum = sum(n * w for n, w in zip(numbers, weights))
        return float(weighted_sum)

    return float(sum(numbers) / len(numbers))

```

