def edit_distance(str1: str, str2: str) -> int:
    """
    Computes the Levenshtein distance between two strings.
    """
    # Check for empty input cases
    if not str1:
        return len(str2)
    if not str2:
        return len(str1)

    # Use dynamic programming with space optimization
    n, m = len(str1), len(str2)

    # Previous and current row of the DP table
    prev_row = list(range(m + 1))

    for i in range(1, n + 1):
        current_row = [i] * (m + 1)
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                current_row[j] = prev_row[j - 1]
            else:
                current_row[j] = min(prev_row[j] + 1,  # Deletion
                                     current_row[j - 1] + 1,  # Insertion
                                     prev_row[j - 1] + 1)  # Substitution
        prev_row = current_row

    return prev_row[-1]

```

