def check_number(num):
    """
    Determines if the number is positive, negative, or zero,
    and whether it is odd or even.
    Returns a tuple indicating ('Positive'/'Negative'/'Zero', 'Odd'/'Even').
    """
    if num > 0:
        pos_neg = "Positive"
    elif num < 0:
        pos_neg = "Negative"
    else:
        pos_neg = "Zero"

    if num % 2 == 0:
        odd_even = "Even"
    else:
        odd_even = "Odd"

    return (pos_neg, odd_even)

