def count_occurrences(sorted_array, x):
    """
    Return the number of occurrences of x in the sorted array `sorted_array`.
    This function uses binary search to find the first and last occurrence of x, making it efficient.
    """
    def binary_search_left(arr, target):
        low, high = 0, len(arr)
        while low < high:
            mid = (low + high) // 2
            if arr[mid] < target:
                low = mid + 1
            else:
                high = mid
        return low

    def binary_search_right(arr, target):
        low, high = 0, len(arr)
        while low < high:
            mid = (low + high) // 2
            if arr[mid] > target:
                high = mid
            else:
                low = mid + 1
        return low

    left_idx = binary_search_left(sorted_array, x)
    right_idx = binary_search_right(sorted_array, x)

    # if x is not found in the array, left_idx will equal right_idx
    if left_idx < len(sorted_array) and sorted_array[left_idx] == x:
        return right_idx - left_idx
    else:
        return 0

```

