def rot13_cipher(input_str):
    """
    Encodes a given string using the ROT13 cipher.
    """
    output_str = []

    for char in input_str:
        if 'a' <= char <= 'z':
            # Calculate rotation within lowercase letters
            rotated_char = chr((ord(char) - ord('a') + 13) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            # Calculate rotation within uppercase letters
            rotated_char = chr((ord(char) - ord('A') + 13) % 26 + ord('A'))
        else:
            rotated_char = char  # Non-alphabetic characters are not transformed
        output_str.append(rotated_char)

    return ''.join(output_str)

