import re


def simple_calculator(expression):
    """
    Evaluates a mathematical expression string for +, -, *, /, and ^.
    """
    def eval_expr(tokens):
        def parse_atom():
            token = tokens.pop(0)
            if token == '(':
                result = parse_expr()
                tokens.pop(0)  # Remove ')'
                return result
            else:
                return float(token)

        def parse_factor():
            result = parse_atom()
            while tokens and tokens[0] == '^':
                tokens.pop(0)
                result **= parse_atom()
            return result

        def parse_term():
            result = parse_factor()
            while tokens and tokens[0] in ('*', '/'):
                op = tokens.pop(0)
                if op == '*':
                    result *= parse_factor()
                elif op == '/':
                    result /= parse_factor()
            return result

        def parse_expr():
            result = parse_term()
            while tokens and tokens[0] in ('+', '-'):
                op = tokens.pop(0)
                if op == '+':
                    result += parse_term()
                elif op == '-':
                    result -= parse_term()
            return result

        return parse_expr()

    expression = re.sub(r'\s+', '', expression)  # Remove spaces
    tokens = re.findall(r'\d+\.?\d*|[()+/*^-]', expression)
    return eval_expr(tokens)

```

