def apply_rules(number, rules):
    """
    Applies a series of rules to a number sequentially.

    Parameters:
    number (int or float): The initial number to which the rules will be applied.
    rules (list of tuples): A list of rules, where each rule is a tuple in the format (operation, value).
                           The operation is a string which can be 'add', 'subtract', 'multiply', or 'divide'.
                           The value is the number to be used in the operation.

    Returns:
    int or float: The final number after all rules have been applied.
    """
    for operation, value in rules:
        if operation == 'add':
            number += value
        elif operation == 'subtract':
            number -= value
        elif operation == 'multiply':
            number *= value
        elif operation == 'divide':
            if value != 0:
                number /= value
            else:
                raise ValueError("Division by zero is not allowed")
        else:
            raise ValueError("Unsupported operation: " + operation)

    return number

```

