def max_depth_of_parentheses(s: str) -> int:
    """
    Returns the maximum depth of nested parentheses within the given string.
    If the string contains unbalanced parentheses, the function returns -1.
    """
    max_depth = 0
    current_depth = 0

    for char in s:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            if current_depth == 0:
                return -1  # Unbalanced case: more closing than opening
            current_depth -= 1

    if current_depth != 0:
        return -1  # Unbalanced case: more opening than closing

    return max_depth

```

