def find_first_and_last(nums, target):
    """
    Returns the indices of the first and last occurrence of the target in the sorted array nums.
    """
    def binary_search(left_condition):
        low, high = 0, len(nums) - 1
        best_index = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                best_index = mid
                if left_condition:
                    high = mid - 1
                else:
                    low = mid + 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return best_index

    first_occurrence = binary_search(True)
    last_occurrence = binary_search(False)
    return [first_occurrence, last_occurrence]

```

