def parse_custom_format(data, mappings):
    """
    Parses a custom formatted string into a dictionary with specific type conversions.

    :param data: A custom formatted string.
    :param mappings: A dictionary specifying the type conversion rules for keys.
    :return: A dictionary with parsed and typed values.
    """
    import re

    def convert_value(key, value):
        # Remove surrounding brackets and split by comma if the value is a list-like string
        if value.startswith('[') and value.endswith(']'):
            value = value[1:-1].split(',')
            value = [v.strip() for v in value]  # strip whitespace around list items
        elif key in mappings:
            wanted_type = mappings[key]
            if wanted_type == int:
                try:
                    value = int(value)
                except ValueError:
                    raise ValueError(f"Cannot convert value '{value}' to int for key '{key}'")
            elif wanted_type == bool:
                if value.lower() == 'true':
                    value = True
                elif value.lower() == 'false':
                    value = False
                else:
                    raise ValueError(f"Cannot convert value '{value}' to bool for key '{key}'")
            elif wanted_type == str:
                value = value.strip()  # strip any extra whitespace
        return value

    result = {}
    # Extract key-value pairs
    pattern = r'(\w+):(\[.*?\]|[^,\[\]]+)'
    matches = re.findall(pattern, data)

    for key, value in matches:
        result[key] = convert_value(key, value)

    return result

```

