def shift_characters(s):
    """
    In a given input string `s`, replace each character with the next character in the ASCII table.
    If a character is 'z' or 'Z', it should wrap around to 'a' or 'A' respectively.
    Ignore non-alphabetical characters in the input string and keep them in their original position.
    """
    result = []

    for char in s:
        if 'a' <= char <= 'y':
            result.append(chr(ord(char) + 1))
        elif char == 'z':
            result.append('a')
        elif 'A' <= char <= 'Y':
            result.append(chr(ord(char) + 1))
        elif char == 'Z':
            result.append('A')
        else:
            result.append(char)

    return ''.join(result)

```

