def shift_cipher(message, shift):
    """
    Applies a shift of a given number on a given message. Preserves the case of alphabetic characters and ignores non-alphabetic characters.

    Args:
    message (str): The input message to be ciphered or deciphered.
    shift (int): The number of positions to shift. Positive for ciphering and negative for deciphering.

    Returns:
    str: The result of applying the shift to the message.
    """
    def shift_character(ch, shift):
        if 'a' <= ch <= 'z':
            return chr((ord(ch) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= ch <= 'Z':
            return chr((ord(ch) - ord('A') + shift) % 26 + ord('A'))
        return ch

    return ''.join(shift_character(c, shift) for c in message)

```

