def diff_dicts(d1, d2):
    """
    Compute the difference between two dictionaries, including nested dictionaries.
    Returns a dictionary containing the differences.
    """
    diff = {}
    all_keys = set(d1.keys()).union(set(d2.keys()))

    for key in all_keys:
        if key in d1 and key not in d2:
            diff[key] = ("removed", d1[key])
        elif key not in d1 and key in d2:
            diff[key] = ("added", d2[key])
        elif d1[key] != d2[key]:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                nested_diff = diff_dicts(d1[key], d2[key])
                if nested_diff:
                    diff[key] = nested_diff
            else:
                diff[key] = ("modified", d1[key], d2[key])
    return diff

```

