def find_pairs(nums, k):
    """
    Returns the number of unique k-difference pairs in the array nums.
    """
    if k < 0:
        return 0

    pairs = set()
    seen = set()

    if k == 0:
        freq = {}
        for number in nums:
            if number in freq:
                freq[number] += 1
            else:
                freq[number] = 1
        for number in freq:
            if freq[number] > 1:
                pairs.add((number, number))
    else:
        for number in nums:
            if (number + k) in seen:
                pairs.add((number, number + k))
            if (number - k) in seen:
                pairs.add((number - k, number))
            seen.add(number)

    return len(pairs)

```

