def is_perfect_cube(n):
    """
    Check if a given number is a perfect cube.
    Returns a tuple (bool, int) where the bool indicates whether the number is a perfect cube,
    and the int is the cube root if it is a perfect cube, otherwise 0.

    Args:
    n: int - the number to be checked

    Returns:
    tuple: (is_cube: bool, cube_root: int)
    """
    if n == 0:
        return (True, 0)

    abs_n = abs(n)
    cube_root = round(abs_n ** (1 / 3))

    if cube_root ** 3 == abs_n:
        return (True, cube_root if n > 0 else -cube_root)
    else:
        return (False, 0)

