def find_unique_substrings(str1, str2):
    """
    Returns all unique shortest sub-strings from two strings.
    """
    def get_all_unique_substrings(s):
        unique_substrs = set()
        n = len(s)
        for length in range(1, n + 1):
            for i in range(n - length + 1):
                unique_substrs.add(s[i:i + length])
        return unique_substrs

    substrs1 = get_all_unique_substrings(str1)
    substrs2 = get_all_unique_substrings(str2)

    all_unique_substrs = substrs1.symmetric_difference(substrs2)

    shortest_substrings = set()
    min_length = float('inf')

    for substr in all_unique_substrs:
        if len(substr) < min_length:
            shortest_substrings = {substr}
            min_length = len(substr)
        elif len(substr) == min_length:
            shortest_substrings.add(substr)

    return list(shortest_substrings)

