def is_perfect_square(n):
    """
    Returns True if n is a perfect square, otherwise returns False.
    """
    if n < 1:
        return False

    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        mid_squared = mid * mid
        if mid_squared == n:
            return True
        elif mid_squared < n:
            left = mid + 1
        else:
            right = mid - 1
    return False

```

