def find_unique_substrings(s: str, k: int) -> list[str]:
    """
    Returns a list of all unique substrings of length k from the input string s.
    """
    if not isinstance(s, str):
        raise TypeError("The input 's' must be a string.")
    if not isinstance(k, int):
        raise TypeError("The input 'k' must be an integer.")
    if k < 1 or k > len(s):
        raise ValueError("The input 'k' must be between 1 and the length of the string 's'.")

    unique_substrings = set()
    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        unique_substrings.add(substring)

    return list(unique_substrings)

```

