from typing import List


def find_missing_ranges(nums: List[int], lower: int, upper: int) -> List[str]:
    """
    Find the missing ranges in the interval [lower, upper] given a sorted list of unique integers nums.
    """
    def format_range(low: int, high: int) -> str:
        if low == high:
            return f"{low}"
        else:
            return f"{low}->{high}"

    missing_ranges = []
    prev = lower - 1

    for i in range(len(nums) + 1):
        if i < len(nums):
            current = nums[i]
        else:
            current = upper + 1

        if prev + 1 <= current - 1:
            missing_ranges.append(format_range(prev + 1, current - 1))

        prev = current

    return missing_ranges

```

