def checkValidString(s: str) -> bool:
    """
    This function checks whether a string with characters '(', ')', and '*' is balanced.
    The '*' can be treated as '(', ')' or an empty string.
    """
    # Error handling for invalid characters
    if not all(c in {'(', ')', '*'} for c in s):
        raise ValueError("Invalid character found in the input string")

    left_balance = right_balance = 0

    # First pass: check for valid left-to-right balance
    for char in s:
        if char == '(' or char == '*':
            left_balance += 1
        else:
            left_balance -= 1

        if left_balance < 0:
            return False

    # Second pass: check for valid right-to-left balance
    for char in reversed(s):
        if char == ')' or char == '*':
            right_balance += 1
        else:
            right_balance -= 1

        if right_balance < 0:
            return False

    return True

```

