def custom_sort(numbers):
    """
    Sorts a list of numbers in ascending order without using built-in sort functions.
    Args:
    - numbers: List[int] - A list of integers.

    Returns:
    - List[int]: A sorted list of integers.
    """
    if not isinstance(numbers, list):
        raise ValueError("Input should be a list.")

    for element in numbers:
        if not isinstance(element, (int, float)):
            raise ValueError("All elements in the list should be numbers.")

    # Implementing a simple bubble sort algorithm
    n = len(numbers)
    for i in range(n):
        for j in range(0, n-i-1):
            if numbers[j] > numbers[j+1]:
                numbers[j], numbers[j+1] = numbers[j+1], numbers[j]
    return numbers

```

