def minCut(s):
    """
    Returns the minimum cuts needed for a palindrome partitioning of s.
    """
    n = len(s)
    if n < 2:
        return 0

    # Create a 2D table to store whether a substring is palindrome or not
    is_palindrome = [[False]*n for _ in range(n)]

    for i in range(n):
        is_palindrome[i][i] = True  # Each single character is a palindrome

    for length in range(2, n+1):  # Check all substrings of length 2 to n
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:  # Substring of two characters
                    is_palindrome[i][j] = True
                else:
                    is_palindrome[i][j] = is_palindrome[i+1][j-1]

    cuts = [float('inf')] * n
    for i in range(n):
        if is_palindrome[0][i]:
            cuts[i] = 0  # No need to cut if whole substring is a palindrome
        else:
            for j in range(i):
                if is_palindrome[j+1][i]:
                    cuts[i] = min(cuts[i], cuts[j] + 1)

    return cuts[-1]

```

