def longestCommonPrefix(strs):
    """
    Finds the longest common prefix in a list of strings.
    """
    if not strs:
        return ""

    def commonPrefix(left, right):
        """
        Returns the common prefix between left and right strings.
        """
        minLength = min(len(left), len(right))
        for i in range(minLength):
            if left[i] != right[i]:
                return left[:i]
        return left[:minLength]

    def longestCommonPrefixRecursively(start, end):
        """
        Recursively finds the longest common prefix in the list of strings from start to end.
        """
        if start == end:
            return strs[start]

        mid = (start + end) // 2
        lcpLeft = longestCommonPrefixRecursively(start, mid)
        lcpRight = longestCommonPrefixRecursively(mid + 1, end)
        return commonPrefix(lcpLeft, lcpRight)

    return longestCommonPrefixRecursively(0, len(strs) - 1)

```

