from typing import List


def word_breaks(s: str, word_dict: List[str]) -> List[str]:
    """
    Finds all possible word breaks for a given string s using a provided dictionary of words.
    """
    def backtrack(start):
        if start == len(s):
            return [[]]

        if start in memo:
            return memo[start]

        results = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in word_dict_set:
                for rest in backtrack(end):
                    results.append([word] + rest)

        memo[start] = results
        return results

    word_dict_set = set(word_dict)
    memo = {}
    results = backtrack(0)
    return [' '.join(words) for words in results]

```

