def reverse_string_ignore_punctuations(s):
    """
    Reverses the string in-place, ignoring punctuation and whitespace characters.
    """
    # Helper function to check if a character is alphanumeric
    def is_alphanumeric(c):
        return c.isalnum()

    # Convert the string to a list to perform in-place swapping
    s_list = list(s)

    # Initialize two pointers
    left, right = 0, len(s) - 1

    while left < right:
        # Ignore non-alphanumeric characters
        if not is_alphanumeric(s_list[left]):
            left += 1
        elif not is_alphanumeric(s_list[right]):
            right -= 1
        else:
            # Swap the characters
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    return ''.join(s_list)

```

