def has_loop(streets: list[tuple[str, str]]) -> bool:
    """
    Determine if there are any loops in the city's street layout.

    :param streets: A list of tuples, each representing two-way streets between intersections.
    :return: True if there exists at least one loop, otherwise False.
    """
    parent = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    # initialize each intersection as its own parent
    for a, b in streets:
        if a not in parent:
            parent[a] = a
        if b not in parent:
            parent[b] = b

    for a, b in streets:
        if find(a) == find(b):
            return True
        union(a, b)

    return False

```

