def analyze_books(books):
    """
    Groups books by their genre and computes the average rating and total pages for each genre.

    :param books: List of dictionaries with each book containing 'title', 'genre', 'rating', and 'pages'.
    :return: Dictionary with genres as keys and another dictionary as values containing 'average_rating' and 'total_pages'.
    """
    genre_stats = {}

    for book in books:
        genre = book['genre']
        rating = book['rating']
        pages = book['pages']

        if genre not in genre_stats:
            genre_stats[genre] = {'total_rating': 0, 'count': 0, 'total_pages': 0}

        genre_stats[genre]['total_rating'] += rating
        genre_stats[genre]['count'] += 1
        genre_stats[genre]['total_pages'] += pages

    result = {}
    for genre, stats in genre_stats.items():
        average_rating = stats['total_rating'] / stats['count'] if stats['count'] > 0 else 0
        total_pages = stats['total_pages']
        result[genre] = {'average_rating': average_rating, 'total_pages': total_pages}

    return result

```

