def aggregate_by_key(data, key):
    """
    Aggregates values by a specified key in a list of dictionaries.

    Parameters:
    - data: list of dictionaries
    - key: the key string to aggregate by

    Returns:
    - A dictionary with unique values of the specified key as keys 
      and the sums of corresponding values as values.
    """
    if not data or key not in data[0]:
        return {}

    result = {}
    for entry in data:
        if key in entry:
            key_value = entry[key]
            if key_value not in result:
                result[key_value] = 0
            if isinstance(entry.get('amount'), (int, float)):
                result[key_value] += entry['amount']
    return result

```

