def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, False otherwise.
    Prime numbers are greater than 1 and have no divisors other than 1 and themselves.
    """
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

```

