def count_valid_bracket_sequences(n: int) -> int:
    """
    Returns the number of valid bracket sequences of length 2 * n.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be non-negative")

    # Function to compute the nth Catalan number
    def catalan_number(n):
        if n == 0 or n == 1:
            return 1
        catalan = [0] * (n + 1)
        catalan[0], catalan[1] = 1, 1
        for i in range(2, n + 1):
            catalan[i] = 0
            for j in range(i):
                catalan[i] += catalan[j] * catalan[i - j - 1]
        return catalan[n]

    return catalan_number(n)

```

