def has_cycle(graph):
    """
    Returns True if there is a cycle in the graph, else False.

    Parameters:
    - graph: a dictionary representing the adjacency list of the graph

    Returns:
    - Boolean value indicating the presence of a cycle
    """
    visited = set()
    rec_stack = set()

    def is_cyclic(v):
        visited.add(v)
        rec_stack.add(v)

        for neighbour in graph[v]:
            if neighbour not in visited:
                if is_cyclic(neighbour):
                    return True
            elif neighbour in rec_stack:
                return True

        rec_stack.remove(v)
        return False

    for node in graph:
        if node not in visited:
            if is_cyclic(node):
                return True

    return False

```

