def find_first_unique_char(s: str) -> int:
    """
    Returns the index of the first non-repeating character in a given string.
    If no such character exists, it returns -1.
    """
    # Dictionary to store the frequency and the first index of each character
    char_frequency = {}

    # Fill the dictionary with frequency and first index
    for index, char in enumerate(s):
        if char in char_frequency:
            char_frequency[char][0] += 1
        else:
            char_frequency[char] = [1, index]

    # Iterate through the dictionary to find the first non-repeating character
    for char in s:
        if char_frequency[char][0] == 1:
            return char_frequency[char][1]

    return -1

```

