        The nth term of the Fibonacci sequence, or an appropriate error message for invalid input.
    """
    if isinstance(n, int) and n > 0:
        if n == 1 or n == 2:
            return 1
        else:
            return fibonacci(n - 1) + fibonacci(n - 2)
    else:
        return "Invalid input. Please enter a positive integer."

