def binary_search_all(arr, target):
    """
    Returns a list of indexes of all occurrences of target in arr.
    """
    def find_leftmost():
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_rightmost():
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left_index = find_leftmost()
    right_index = find_rightmost()

    # Verify if the target value is within the range of found indices
    if left_index <= right_index and arr[left_index] == target and arr[right_index] == target:
        return list(range(left_index, right_index + 1))
    else:
        return []

