def first_unique_character(s):
    """
    Returns the index and character of the first unique character in the string s.
    If no unique character, returns None, None.
    """
    char_count = {}
    char_index = {}

    for index, char in enumerate(s):
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
            char_index[char] = index

    unique_chars = [char for char in char_count if char_count[char] == 1]
    if not unique_chars:
        return None, None

    first_unique_char = min(unique_chars, key=lambda char: char_index[char])
    return char_index[first_unique_char], first_unique_char

