def longest_substring_with_k_repeats(s, k):
    """
    Find the length of the longest substring where each character appears at least k times.

    :param s: Input string
    :param k: Minimum number of times each character must appear in the substring
    :return: Length of the longest substring
    """
    def longest_substring_helper(s, k):
        if not s:
            return 0

        count = {}
        for char in s:
            count[char] = count.get(char, 0) + 1

        for mid in range(len(s)):
            if count[s[mid]] < k:
                left = longest_substring_helper(s[:mid], k)
                right = longest_substring_helper(s[mid+1:], k)
                return max(left, right)

        return len(s)

    return longest_substring_helper(s, k)

