def fibonacci(n, cache=None):
    """
    Returns the nth Fibonacci number using recursion and caching.
    """
    if cache is None:
        cache = {}

    if n in cache:
        return cache[n]

    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        cache[n] = fibonacci(n-1, cache) + fibonacci(n-2, cache)
        return cache[n]

