def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string and its frequency.
    If no such character exists, return 'No non-repeating characters.'

    :param s: str
    :return: (char, frequency) or 'No non-repeating characters.'
    """
    char_count = {}

    # Count each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first non-repeating character
    for char in s:
        if char_count[char] == 1:
            return (char, 1)

    return 'No non-repeating characters.'

```

