def intersection(list1, list2):
    """
    Returns a list of integers that appear in both list1 and list2, maintaining the order of elements as they appear in list1.
    """
    result = []
    list2_count = {}

    # Count occurrences of elements in list2
    for num in list2:
        if num in list2_count:
            list2_count[num] += 1
        else:
            list2_count[num] = 1

    # Find intersection while maintaining order of list1
    for num in list1:
        if num in list2_count and list2_count[num] > 0:
            result.append(num)
            list2_count[num] -= 1

    return result

```

