        return "Invalid water intake."

    if physical_activity_minutes < 0:
        return "Invalid physical activity time."

    if physical_activity_minutes == 0:
        if water_intake_liters < 2:
            return "Hydration level: Low"
        elif water_intake_liters <= 3:
            return "Hydration level: Normal"
        else:
            return "Hydration level: High"
    else:
        if water_intake_liters / physical_activity_minutes < 0.033:
            return "Hydration level: Low"
        elif water_intake_liters / physical_activity_minutes <= 0.05:
            return "Hydration level: Normal"
        else:
