def fizzbuzz_list(n):
    """
    Returns a list of strings for the FizzBuzz game from 1 to n.
    """
    if n < 1:
        return []
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

