def rpn_calculator(tokens):
    """
    Simulate the operation of a simplified stack-based calculator using Reverse Polish Notation (RPN).

    Parameters:
    tokens (list of str): A list of strings where each string is either an integer or an operator ("+", "-", "*", "/").

    Returns:
    int: The final result after processing all operations.
    """
    stack = []

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                # Perform integer division as required
                stack.append(int(a / b))
        else:
            stack.append(int(token))

    return stack.pop()

```

